// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(this));
    }

    function _run(address sender, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        bool reverted;
        try c.CashOut(0) {} catch { return; }
        try c.Deposit{value: depositAmount}() { reverted = false; }
        catch { reverted = true; }
        assertTrue(!((depositAmount >= c.MinDeposit()) && reverted));
    }

    function testFuzz_run(address sender, uint256 depositAmount) public {
        _run(sender, depositAmount);
    }

    receive() external payable {}
}
